      "module_name": "Mathlib.RingTheory.GradedAlgebra.HomogeneousLocalization",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {A : Type u_2} {σ : Type u_3} [inst : CommRing A] [inst_1 : SetLike σ A] {𝒜 : ι → σ} (x : Submonoid A)\n  {α : Type u_4} [inst_2 : SMul α A] [inst_3 : SMulMemClass σ α A] (c : HomogeneousLocalization.NumDenSameDeg 𝒜 x)\n  (m : α), ↑(m • c).den = ↑c.den"
    },
    {
      "name": "Nat.sum_div",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {s : Finset ι} {f : ι → ℕ} {n : ℕ}, (∀ i ∈ s, n ∣ f i) → (∑ i ∈ s, f i) / n = ∑ i ∈ s, f i / n"
    },
    {
      "name": "Int.sum_div",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_5} {s : Finset ι} {f : ι → ℤ} {n : ℤ}, (∀ i ∈ s, n ∣ f i) → (∑ i ∈ s, f i) / n = ∑ i ∈ s, f i / n"
    },
    {
      "name": "Multiset.dvd_sum",
      "module_name": "Mathlib.Algebra.BigOperators.Ring.Multiset",
      "kind": "theorem",
      "type": "∀ {R : Type u_4} [inst : NonUnitalSemiring R] {s : Multiset R} {a : R}, (∀ (x : R), x ∈ s → a ∣ x) → a ∣ s.sum"
    },
    {
      "name": "Dvd.dvd.scaleRoots",
      "module_name": "Mathlib.RingTheory.Polynomial.ScaleRoots",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (p q : Polynomial R) {r : R} [NoZeroDivisors R],\n  p ∣ q → p.scaleRoots r ∣ q.scaleRoots r"
    }
  ]
